) AS src (OldSupplierId, SupplierName, SupplierRef, SupplierShortName, SupplierType, Phone, Email, Web,
          VatNumber, TaxNumber, Remarks, CountryId, CreatedDate)
ON tgt.SupplierName = src.SupplierName COLLATE DATABASE_DEFAULT
WHEN NOT MATCHED BY TARGET THEN
    -- SupplierCode starts blank, same as the app's own sp_SetSupplier: it inserts '' then updates the code
    -- from proj.fn_InitialsFromName() once the new identity value is known (below), so migrated suppliers
    -- get codes in the exact same format the application generates for a supplier created through the UI.
    INSERT (SupplierCode, SupplierName, SupplierRef, SupplierShortName, SupplierType, Phone, Email, Web,
            CurrencyId, PaymentTermsId, VatNumber, TaxNumber, Remarks, IsActive, IsApprovedVendor,
            IsOnHold, CountryId, CreatedBy, CreatedDate)
    VALUES (N'', src.SupplierName, src.SupplierRef, src.SupplierShortName, src.SupplierType, src.Phone, src.Email, src.Web,
            2, 4, src.VatNumber, src.TaxNumber, src.Remarks, 1, 0,
            0, src.CountryId, N'MIGRATION-ENGSERVICE_FZEERP', src.CreatedDate)
OUTPUT src.OldSupplierId, INSERTED.SupplierId INTO #Map (OldSupplierId, NewSupplierId);

DECLARE @Inserted INT = (SELECT COUNT(*) FROM #Map);
PRINT 'Suppliers inserted this run: ' + CAST(@Inserted AS VARCHAR(10)) + ' of 490 source rows (the rest already existed by name).';

UPDATE t SET t.SupplierCode = proj.fn_InitialsFromName(t.SupplierName) + N'-' + CAST(t.SupplierId AS NVARCHAR(20))
FROM PROJ.TBL_SUPPLIER t
JOIN #Map m ON m.NewSupplierId = t.SupplierId;

