INSERT INTO PROJ.TBL_SUPPLIER_ADDRESS (SupplierId, AddressType, AddressLine1, City, POBox, CountryId, IsDefault, IsActive, CreatedBy, CreatedDate)
SELECT m.NewSupplierId, 'Head Office', a.AddressLine1, a.City, a.POBox, a.CountryId, 1, 1, N'MIGRATION-ENGSERVICE_FZEERP', GETDATE()
